awaitable<void> on_connection(tcp::socket sock) {
  char buf[4096];
  for (;;) {
    auto n = co_await sock.async_read_some(asio::buffer(buf), asio::use_awaitable);
    auto reply = decode(buf, n);              // carries reply.correlation_id
    if (auto node = pending.extract(reply.correlation_id))
      node.mapped().promise.set_value(std::move(reply));   // same table, linear code
  }
}
